import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import net.farmingtales.ftboss.boss.ai.NativeManorDamageBridgeInstaller;
public final class ManorOriginalSharingBudgetProofV1 {
    private static int checks;
    private static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static ClassNode read(ZipFile jar,String name)throws Exception{ClassNode node=new ClassNode();new ClassReader(jar.getInputStream(jar.getEntry(name+".class")).readAllBytes()).accept(node,ClassReader.SKIP_DEBUG);return node;}
    private static String graph(MethodNode method){return NativeManorDamageBridgeInstaller.graph(method);}
    private static final class RulesLoader extends ClassLoader {Class<?> pure(byte[] payload){return defineClass(null,payload,0,payload.length);}}
    private static List<AbstractInsnNode> code(MethodNode method){return Arrays.stream(method.instructions.toArray()).filter(value->value.getOpcode()>=0).toList();}
    private static boolean accepted(float initial,float modified){return Float.isFinite(modified)&&modified<=300.0F&&!(initial>0.0F&&modified<=0.0F);}
    public static void main(String[] args)throws Exception{
        JsonObject receipt=new JsonObject();try(ZipFile original=new ZipFile(args[0]);ZipFile candidate=new ZipFile(args[1])){
            String rulesName="net/farmingtales/ftboss/util/ManorDamageRules";ClassNode oldRules=read(original,rulesName),newRules=read(candidate,rulesName);require(oldRules.methods.size()==newRules.methods.size(),"Pure original rules method set retained");for(MethodNode method:oldRules.methods){MethodNode current=newRules.methods.stream().filter(value->value.name.equals(method.name)&&value.desc.equals(method.desc)).findFirst().orElseThrow();require(graph(method).equals(graph(current)),"Complete original pure rule method graph "+method.name);}
            Class<?> pure=new RulesLoader().pure(original.getInputStream(original.getEntry(rulesName+".class")).readAllBytes());var ignored=pure.getMethod("ignored",float.class);var remaining=pure.getMethod("remainingDamage",float.class,boolean.class,boolean.class);
            for(float amount:new float[]{Float.NEGATIVE_INFINITY,-1.0F,-0.0F,0.0F,Float.MIN_VALUE,1.0F,299.99F,300.0F,Math.nextUp(300.0F),Float.MAX_VALUE,Float.POSITIVE_INFINITY,Float.NaN})require((boolean)ignored.invoke(null,amount)==(!Float.isFinite(amount)||amount>300.0F),"Original final amount rejection boundary "+amount);
            for(int index=0;index<=2048;index++)for(boolean sparrow:new boolean[]{false,true})for(boolean mini:new boolean[]{false,true}){float amount=index*0.25F,expected=amount;if(sparrow)expected-=expected*0.5F;if(mini)expected-=expected*0.1F;require(Float.floatToIntBits((float)remaining.invoke(null,amount,sparrow,mini))==Float.floatToIntBits(expected),"Original sequential presence budget");}
            ClassNode finalDamage=read(original,"net/farmingtales/ftboss/boss/ai/ManorFinalDamage");MethodNode settle=finalDamage.methods.stream().filter(value->value.name.equals("settle")).findFirst().orElseThrow();List<AbstractInsnNode> instructions=code(settle);List<String> definitions=new ArrayList<>();int share=-1;
            for(int index=0;index<instructions.size();index++){AbstractInsnNode value=instructions.get(index);if(value instanceof VarInsnNode variable&&variable.getOpcode()==Opcodes.FSTORE&&variable.var==4){require(instructions.get(index-1) instanceof MethodInsnNode,"Original budget assignment directly follows reduction/cap call");definitions.add(((MethodInsnNode)instructions.get(index-1)).name);}if(value instanceof MethodInsnNode call&&call.name.equals("ftboss$shareManorDamage")){require(share<0,"Unique original helper share call");share=index;}}
            require(definitions.equals(List.of("ftboss$reduceManorDamage","cap")),"Only original armor/magic reduction and cap assign local4");require(share>=3&&instructions.get(share-2) instanceof VarInsnNode budget&&budget.getOpcode()==Opcodes.FLOAD&&budget.var==4,"Original helper sharing consumes reduced/capped local4");require(instructions.get(share-1) instanceof VarInsnNode source&&source.var==1&&source.getOpcode()==Opcodes.ALOAD,"Original helper share source retained");
            List<Integer> initialGuards=new ArrayList<>();for(int index=0;index+3<instructions.size();index++)if(instructions.get(index) instanceof VarInsnNode initial&&initial.var==11&&initial.getOpcode()==Opcodes.FLOAD&&instructions.get(index+1).getOpcode()==Opcodes.FCONST_0&&instructions.get(index+2).getOpcode()==Opcodes.FCMPL&&instructions.get(index+3).getOpcode()==Opcodes.IFLE)initialGuards.add(index);require(initialGuards.size()==1,"Unique original pre-modifier positive-amount guard");int index=initialGuards.getFirst();require(instructions.get(index+4) instanceof VarInsnNode modified&&modified.var==13&&modified.getOpcode()==Opcodes.FLOAD&&instructions.get(index+5).getOpcode()==Opcodes.FCONST_0&&instructions.get(index+6).getOpcode()==Opcodes.FCMPG&&instructions.get(index+7).getOpcode()==Opcodes.IFGT,"Original zero modifier rejects only when original pre-modifier amount was positive");
            require(accepted(0,0),"Original fully absorbed zero still permits helper share");require(!accepted(1,0),"Original positive to zero modifier prevents share");require(accepted(1,0.5F)&&!accepted(1,301)&&!accepted(0,Float.NaN),"Original positive modifier and invalid amount guards");require(accepted(0,-1),"Original negative mutable amount with original zero is not silently redefined");
            require(!(!Float.isFinite(0)||0>=0),"Negative control catches wrongly ignoring zero");require(!accepted(1,0)&&accepted(0,0),"Negative control catches collapsing absorbed zero and zero modification");
            receipt.addProperty("originalSettleGraph",graph(settle));receipt.addProperty("fullPureRuleMethods",oldRules.methods.size());receipt.addProperty("originalBudgetLocal",4);receipt.addProperty("originalZeroAbsorbedSharingPermitted",true);receipt.addProperty("originalPositiveToZeroModifierSharingRejected",true);receipt.addProperty("negativeMutableAmountWithInitialZeroNotCoveredByNativeMatrix",true);
        }
        receipt.addProperty("checks",checks);receipt.addProperty("negativeControls",2);receipt.addProperty("gameplayMethodsInvoked",false);receipt.addProperty("pureRulesOnlyInvoked",true);receipt.addProperty("resourceBytesExported",false);Files.writeString(Path.of(args[2]),new GsonBuilder().setPrettyPrinting().create().toJson(receipt));System.out.println("checks="+checks+";originalBudgetLocal=4;originalPureRulesAndZeroAbsorptionGuardVerified=true;negativeControls=2;");
    }
}
